function addBook(items,book) {if(!items.some(item=>item.id===book.id))items.push(book);}
async function operation_search(input,nori) {
  const programs=createPrograms(input,nori);
  const address=input.cursor?.url || required(await apply(programs,rules.searchRequest,'',{}),nori,'/request/url');
  const response=await load(programs,address,nori);
  const selected=rows(await apply(programs,rules.search.bookList,response.value,{url:response.url}),nori);
  const items=[];for(const row of selected)addBook(items,await toBook(programs,rules.search,row,input,nori));
