  const values=await fields(programs,map,row);
  const address=required(values.bookUrl || rowValue(programs,row,['bookUrl','book_url','detailUrl','url','href','link'],'a','href'),nori,'/book/locator');
  const decoded=decodeLocator(address,nori);
  const locator=address.startsWith('data:')?{parameters:decoded}:{url:nori.url.resolve(address,programs.baseURL)};
  if(['audio','video'].includes(decoded.tab))nori.fail('unsupported_feature','','/book/kind');
