  const programs=createPrograms(input,nori),choices=await directories(input,nori,programs);
  return {fields:choices.length?[{id:'directory',title:'分类',control:'select',defaultValue:choices[0].id,options:choices.map(x=>({value:x.id,title:x.title}))}]:[]};
