  const response=await load(programs,address,nori);
  const data=rules.detail.init?await apply(programs,rules.detail.init,response.value,{url:address}):response.value;
  const values=await fields(programs,rules.detail,data,{url:address});
  const book={...input.book,title:required(values.name || input.book.title,nori,'/book/title')};
  if(values.author)book.authors=[text(values.author)];if(values.intro)book.summary=summary(values.intro,nori);
