import {createPrograms} from './programs.js';
const rules = {"search": {"author": "ruleSearch_author", "bookList": "ruleSearch_bookList", "bookUrl": "ruleSearch_bookUrl", "coverUrl": "ruleSearch_coverUrl", "kind": "ruleSearch_kind", "lastChapter": "ruleSearch_lastChapter", "name": "ruleSearch_name"}, "catalog": {"author": "ruleSearch_author", "bookList": "ruleSearch_bookList", "bookUrl": "ruleSearch_bookUrl", "coverUrl": "ruleSearch_coverUrl", "kind": "ruleSearch_kind", "lastChapter": "ruleSearch_lastChapter", "name": "ruleSearch_name"}, "detail": {"intro": "ruleBookInfo_intro", "tocUrl": "ruleBookInfo_tocUrl"}, "chapters": {"chapterList": "ruleToc_chapterList", "chapterName": "ruleToc_chapterName", "chapterUrl": "ruleToc_chapterUrl"}, "content": {"content": "ruleContent_content"}, "searchRequest": "searchUrl", "discovery": "exploreUrl", "catalogHomepage": false};

