}

function secureImageURL(address) {
  const value = text(address);
  if (!value) return '';
  if (value.startsWith('//')) return 'https:' + value;
  return value.replace(/^http:\/\//i, 'https://');
}

function imageMediaType(address) {
  const path = address.split(/[?#]/, 1)[0].toLowerCase();
  if (path.endsWith('.webp')) return 'image/webp';
  if (path.endsWith('.png')) return 'image/png';
  return 'image/jpeg';
}

function imageAsset(address, id, role, endpoint) {
  const url = secureImageURL(address);
  if (!url) return undefined;
  return { id: id, role: role, mediaType: imageMediaType(url), source: { url: url, endpoint: endpoint } };
}

function chapterImageURLs(body, nori) {
  const match = body.match(/chapter_img_list\s*:\s*(\[[^\]]*\])/);
  if (!match) nori.fail('value_invalid', '章节页没有图片列表', '/chapter_img_list');
  let urls;
  try { urls = JSON.parse(match[1]); }
  catch { nori.fail('value_invalid', '章节图片列表不是合法 JSON', '/chapter_img_list'); }
  if (!Array.isArray(urls) || urls.length === 0) nori.fail('value_invalid', '章节图片列表为空', '/chapter_img_list');
  return urls.map(function (url) { return typeof url === 'string' ? secureImageURL(url) : ''; });
}

function comicTags(value) {
  if (typeof value !== 'string') return [];
  return value.split('|').map(function (tag) {
    const parts = tag.split(',');
    return text(parts.length > 1 ? parts[parts.length - 1] : parts[0]);
  }).filter(Boolean);
}

function recordBook(record, nori) {
  const id = text(record.comic_id || record.comic_newid);
  const title = text(record.comic_name);
  if (!id || !title) return null;
  const book = {
    id: id,
    title: title,
    kind: 'comic',
    locator: { url: nori.url.resolve('/' + id + '/', BASE) }
  };
  const author = text(record.comic_author);
  if (author) book.authors = [author];
  const summary = text(record.cartoon_desc || record.comic_desc);
  if (summary) book.summary = summary;
  const tags = comicTags(record.comic_type);
  const attributes = [];
  const latest = text(record.last_chapter_name);
  if (latest) attributes.push({ name: '最新章节', value: latest });
  if (record.renqi !== undefined && record.renqi !== null) attributes.push({ name: '人气', value: String(record.renqi) });
  if (tags.length || attributes.length) book.metadata = Object.assign({}, tags.length ? { tags: tags } : {}, attributes.length ? { attributes: attributes } : {});
  const cover = imageAsset(record.cover_img, 'cover:' + id, 'cover', 'covers');
  if (cover) book.cover = cover;
  return book;
}

function cardBook(card, pageURL, nori, latestPage) {
  const titleSelector = latestPage ? '.comic-name a' : 'h3.acgn-title a';
  const titleNode = nori.dom.select(card, titleSelector) || nori.dom.select(card, 'a.acgn-thumbnail');
  const href = titleNode ? nori.dom.attr(titleNode, 'href') : null;
  const title = titleNode ? nori.dom.text(titleNode).trim() : '';
  const match = typeof href === 'string' ? href.match(/^\/(\d+)\//) : null;
  if (!match || !title) return null;
  const id = match[1];
  const book = {
    id: id,
    title: title,
    kind: 'comic',
    locator: { url: nori.url.resolve(href, pageURL) }
  };
  const latestNode = nori.dom.select(card, latestPage ? '.comic-chapter a' : 'a.latest-cartoon');
  const latest = latestNode ? nori.dom.text(latestNode).trim() : '';
  if (latest) book.metadata = { attributes: [{ name: '最新章节', value: latest }] };
  const coverNode = latestPage ? null : nori.dom.select(card, 'img.cover');
  const coverURL = coverNode ? (nori.dom.attr(coverNode, 'data-src') || nori.dom.attr(coverNode, 'src')) : '';
  const cover = imageAsset(coverURL, 'cover:' + id, 'cover', 'covers');
  if (cover) book.cover = cover;
