}

function nextPath(href, currentPath, nori) {
  const value = text(href);
  if (!value) return null;
  const prefix = 'https://' + WEB_HOST;
  if (value.startsWith(prefix)) return webPath(value, nori);
  if (value.startsWith('/') && !value.startsWith('//')) return value;
  const directory = currentPath.slice(0, currentPath.lastIndexOf('/') + 1);
  return webPath(directory + value, nori);
}

export function filters(input, nori) {
  return { fields: input.scope === 'search' ? [] : [{ id: 'category', title: '分类', control: 'select', defaultValue: '/gengxin/', options: CATEGORY_OPTIONS }] };
}

export async function search(input, nori) {
  const query = text(input.query);
  if (!query) return { items: [], next: null };
  const response = await nori.http.request({
    endpoint: 'web', method: 'GET', path: '/api/getsortlist/',
    query: { search_key: query }
  });
  const payload = response.json();
  if (payload.status !== 0 || !Array.isArray(payload.data)) {
    nori.fail('source_error', '看漫画搜索接口返回异常', '/response/data');
  }
  const items = [];
  for (const record of payload.data) {
    const book = recordBook(record, nori);
    if (book && !items.some(function (item) { return item.id === book.id; })) items.push(book);
  }
  return { items: items, next: null };
}

export async function catalog(input, nori) {
  const currentPath = typeof input.cursor === 'string' && input.cursor.startsWith('/')
    ? webPath(input.cursor, nori)
