  const response = await nori.http.request({
    endpoint: 'web', method: 'GET', path: webPath(address, nori),
    query: { _nori: Date.now() }, headers: { 'Cache-Control': 'no-cache', Pragma: 'no-cache' }
  });
  const urls = chapterImageURLs(response.body, nori);
  nori.cache.set('chapter-images:' + webPath(address, nori), urls, { ttlMs: 10000 });
  const assets = {};
  const blocks = [];
  for (let index = 0; index < urls.length; index++) {
    const url = secureImageURL(urls[index]);
