  };
}

export async function resolveResource(input, nori) {
  const locator = input.asset && input.asset.source && input.asset.source.locator;
  const chapterPath = locator && locator.chapterPath;
  const index = locator && locator.index;
  if (typeof chapterPath !== 'string' || !Number.isInteger(index) || index < 0) {
    nori.fail('value_invalid', '漫画图片资源定位无效', '/asset/source/locator');
  }
  const path = webPath(chapterPath, nori);
  const cacheKey = 'chapter-images:' + path;
  let urls = nori.cache.get(cacheKey);
  if (!Array.isArray(urls)) {
    const response = await nori.http.request({
      endpoint: 'web', method: 'GET', path: path,
      query: { _nori: Date.now() }, headers: { 'Cache-Control': 'no-cache', Pragma: 'no-cache' }
    });
    urls = chapterImageURLs(response.body, nori);
    nori.cache.set(cacheKey, urls, { ttlMs: 10000 });
  }
  const url = urls[index];
  if (typeof url !== 'string' || !url) nori.fail('value_invalid', '漫画图片页码超出范围', '/asset/source/locator/index');
  return { url: url, endpoint: 'chapterImages' };
}

